// The existing single-edit API works. Preserve it while extending this module.
function checkEdit(source,edit){
  if(typeof source!=='string'||edit===null||typeof edit!=='object'||Array.isArray(edit)
     ||!Number.isSafeInteger(edit.start)||!Number.isSafeInteger(edit.end)
     ||edit.start<0||edit.start>edit.end||edit.end>source.length
     ||typeof edit.before!=='string'||typeof edit.after!=='string')throw Error('invalid edit');
  if(source.slice(edit.start,edit.end)!==edit.before)throw Error('preimage mismatch');
}
export function applyEdit(source,edit){
  checkEdit(source,edit);
  return source.slice(0,edit.start)+edit.after+source.slice(edit.end);
}
export function applyTransaction(source,edits){
  if(typeof source!=='string')throw Error('invalid source');
  if(!Array.isArray(edits))throw Error('invalid edits');

  // Validate every edit against the original source before applying anything.
  for(const edit of edits)checkEdit(source,edit);

  const n=edits.length;

  // Partition edits into nonempty ranges and insertions (start === end).
  const ranges=[];
  const insertions=[];
  for(const e of edits){
    if(e.start<e.end)ranges.push({start:e.start,end:e.end});
    else insertions.push(e.start);
  }

  // Conflict: two nonempty ranges whose half-open intervals overlap.
  // Sort by start (then end) and track the running max end.
  ranges.sort((a,b)=>a.start-b.start||a.end-b.end);
  let maxEnd=-1;
  for(const r of ranges){
    if(r.start<maxEnd)throw Error('conflicting edits');
    if(r.end>maxEnd)maxEnd=r.end;
  }

  // Conflict: two insertions at the same position.
  const seenPos=new Set();
  for(const p of insertions){
    if(seenPos.has(p))throw Error('conflicting edits');
    seenPos.add(p);
  }

  // Conflict: an insertion at p where some range [s,e) has s <= p <= e.
  // ranges is sorted by start; build a prefix max-end for binary search.
  const rStart=ranges.map(r=>r.start);
  const prefixMaxEnd=[];
  for(let i=0;i<ranges.length;i++){
    const e=ranges[i].end;
    prefixMaxEnd.push(i===0?e:Math.max(prefixMaxEnd[i-1],e));
  }
  for(const p of insertions){
    let lo=0,hi=rStart.length-1,idx=-1;
    while(lo<=hi){
      const mid=(lo+hi)>>1;
      if(rStart[mid]<=p){idx=mid;lo=mid+1;}
      else hi=mid-1;
    }
    if(idx>=0&&prefixMaxEnd[idx]>=p)throw Error('conflicting edits');
  }

  // Apply all edits simultaneously. Every event uses original-source
  // coordinates, so ordering them by position makes the result independent of
  // the input order and preserves every untouched code unit exactly.
  const events=edits.map(e=>({start:e.start,end:e.end,after:e.after}));
  events.sort((a,b)=>a.start-b.start);
  let out='';
  let pos=0;
  for(const ev of events){
    out+=source.slice(pos,ev.start)+ev.after;
    pos=ev.end;
  }
  out+=source.slice(pos,source.length);
  return {text:out,applied:n};
}

import {readFileSync,realpathSync} from 'node:fs';
import {resolve} from 'node:path';
import {fileURLToPath} from 'node:url';

function isMainModule(){
  const entry=process.argv[1];
  if(!entry)return false;
  let entryPath;
  try{entryPath=realpathSync(resolve(entry));}
  catch{try{entryPath=resolve(entry);}catch{return false;}}
  let selfPath;
  try{selfPath=fileURLToPath(import.meta.url);}catch{return false;}
  let selfReal;
  try{selfReal=realpathSync(selfPath);}catch{selfReal=selfPath;}
  return entryPath===selfReal;
}

function runCli(){
  const fail=(msg)=>{
    process.stderr.write(msg+'\n');
    process.exitCode=2;
  };
  const args=process.argv.slice(2);
  if(args.length!==1){
    fail('usage: node patch-transaction.js INPUT_JSON_FILE');
    return;
  }
  const file=args[0];
  let raw;
  try{raw=readFileSync(file,'utf8');}
  catch{fail('cannot read input file');return;}
  let data;
  try{data=JSON.parse(raw);}
  catch{fail('invalid JSON');return;}
  const obj=data&&typeof data==='object'?data:{};
  let result;
  try{
    result=applyTransaction(obj.source,obj.edits);
  }catch(err){
    fail('invalid transaction: '+(err&&err.message?err.message:String(err)));
    return;
  }
  process.stdout.write(JSON.stringify(result)+'\n');
  process.exitCode=0;
}

if(isMainModule())runCli();

