import test,{before,after} from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,writeFileSync,rmSync,existsSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {applyEdit,applyTransaction} from '../patch-transaction.js';

const modulePath=fileURLToPath(new URL('../patch-transaction.js',import.meta.url));
const edit=(start,end,before,after)=>({start,end,before,after});

let dir;
before(()=>{
  dir=mkdtempSync(join(tmpdir(),'patch-txn-'));
});
after(()=>{
  if(dir&&existsSync(dir))rmSync(dir,{recursive:true,force:true});
});

function runCli(args){
  return spawnSync(process.execPath,[modulePath,...args],{encoding:'utf8'});
}
function writeJson(name,value){
  const p=join(dir,name);
  writeFileSync(p,JSON.stringify(value),'utf8');
  return p;
}
function writeRaw(name,text){
  const p=join(dir,name);
  writeFileSync(p,text,'utf8');
  return p;
}

test('existing applyEdit still works',()=>{
  assert.equal(applyEdit('abc',edit(1,2,'b','LONG')),'aLONGc');
});

test('applies all edits using original coordinates',()=>{
  const edits=[edit(3,5,'de','X'),edit(0,1,'a','LONG')];
  assert.deepEqual(applyTransaction('abcdef',edits),{text:'LONGbcXf',applied:2});
  assert.deepEqual(applyTransaction('abcdef',[...edits].reverse()),{text:'LONGbcXf',applied:2});
});

test('adjacent and disjoint ranges are fine',()=>{
  assert.deepEqual(applyTransaction('abcd',[edit(0,2,'ab','x'),edit(2,4,'cd','y')]),{text:'xy',applied:2});
  assert.deepEqual(applyTransaction('abcdef',[edit(0,1,'a','A'),edit(4,6,'ef','E')]),{text:'AbcdE',applied:2});
});

test('insertions at distinct positions outside ranges are fine',()=>{
  assert.deepEqual(applyTransaction('abcd',[edit(1,3,'bc','X'),edit(0,0,'','P'),edit(4,4,'','Q')]),{text:'PaXdQ',applied:3});
});

test('multiple insertions in the same gap are fine',()=>{
  assert.deepEqual(applyTransaction('abc',[edit(0,0,'','a'),edit(3,3,'','c'),edit(1,1,'','b')]),{text:'aabbcc',applied:3});
});

test('overlapping ranges conflict',()=>{
  assert.throws(()=>applyTransaction('abcdef',[edit(0,3,'abc','X'),edit(2,5,'cde','Y')]),Error);
});

test('identical ranges conflict',()=>{
  assert.throws(()=>applyTransaction('ab',[edit(0,2,'ab','X'),edit(0,2,'ab','Y')]),Error);
});

test('insertion touching a range endpoint conflicts',()=>{
  assert.throws(()=>applyTransaction('abcd',[edit(1,3,'bc','X'),edit(1,1,'','Y')]),Error);
  assert.throws(()=>applyTransaction('abcd',[edit(1,3,'bc','X'),edit(3,3,'','Y')]),Error);
  assert.throws(()=>applyTransaction('abcd',[edit(1,3,'bc','X'),edit(2,2,'','Y')]),Error);
});

test('two insertions at the same position conflict',()=>{
  assert.throws(()=>applyTransaction('ab',[edit(0,0,'','X'),edit(0,0,'','Y')]),Error);
  assert.throws(()=>applyTransaction('ab',[edit(0,0,'',''),edit(0,0,'','')]),Error);
});

test('empty transaction returns source unchanged',()=>{
  assert.deepEqual(applyTransaction('tail\r\n',[]),{text:'tail\r\n',applied:0});
});

test('empty source allows one insertion at zero',()=>{
  assert.deepEqual(applyTransaction('',[edit(0,0,'','new')]),{text:'new',applied:1});
  assert.throws(()=>applyTransaction('',[edit(0,0,'','a'),edit(0,0,'','b')]),Error);
  assert.throws(()=>applyTransaction('',[edit(1,1,'','a')]),Error);
});

test('no-op edits are valid and counted',()=>{
  assert.deepEqual(applyTransaction('abc',[edit(1,2,'b','b'),edit(0,0,'','')]),{text:'abc',applied:2});
});

test('preserves CR/LF and final newline',()=>{
  const source='a\r\nb\n';
  assert.deepEqual(applyTransaction(source,[edit(1,3,'\r\n','/')]),{text:'a/b\n',applied:1});
});

test('unicode code units are preserved',()=>{
  // 'é' is a single code unit here; surrogate pairs are two code units.
  const source='a\u{1F600}b'; // a, 😀 (two code units), b => length 4
  assert.equal(source.length,4);
  assert.deepEqual(applyTransaction(source,[edit(0,1,'a','Z')]),{text:'Z\u{1F600}b',applied:1});
});

test('does not mutate the input array or edit objects',()=>{
  const e1=edit(0,1,'a','X');
  const e2=edit(3,5,'de','Y');
  const edits=[e1,e2];
  const snapshot=JSON.stringify(edits);
  applyTransaction('abcdef',edits);
  assert.equal(JSON.stringify(edits),snapshot);
  assert.equal(edits.length,2);
  assert.equal(e1.start,0);
  assert.equal(e1.before,'a');
  assert.equal(e2.after,'Y');
});

test('invalid arguments throw',()=>{
  assert.throws(()=>applyTransaction(123,[edit(0,1,'x','y')]),Error);
  assert.throws(()=>applyTransaction(null,[]),Error);
  assert.throws(()=>applyTransaction('abc',null),Error);
  assert.throws(()=>applyTransaction('abc','nope'),Error);
  assert.throws(()=>applyTransaction('abc',[null]),Error);
  assert.throws(()=>applyTransaction('abc',['x']),Error);
  assert.throws(()=>applyTransaction('abc',[{start:0,end:1}]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(1.5,2,'b','x')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(-1,0,'','x')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(0,4,'','x')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(2,1,'','x')]),Error);
  // preimage mismatch
  assert.throws(()=>applyTransaction('abc',[edit(0,1,'z','x')]),Error);
});

test('unknown fields are ignored (no coercion)',()=>{
  const e={start:0,end:1,before:'a',after:'X',extra:'ignored',id:42,nested:{}};
  assert.deepEqual(applyTransaction('abc',[e]),{text:'Xbc',applied:1});
  assert.equal(e.extra,'ignored');
});

test('CLI: success prints one JSON line, exit 0, no stderr',()=>{
  const p=writeJson('ok.json',{source:'abcdef',edits:[edit(0,1,'a','LONG'),edit(3,5,'de','X')]});
  const r=runCli([p]);
  assert.equal(r.status,0);
  assert.equal(r.stderr,'');
  assert.equal(r.stdout,JSON.stringify({text:'LONGbcXf',applied:2})+'\n');
});

test('CLI: extra fields are ignored',()=>{
  const p=writeJson('extra.json',{source:'abc',edits:[],extra:'ignored',nested:{a:1},edits2:[1]});
  const r=runCli([p]);
  assert.equal(r.status,0);
  assert.equal(r.stderr,'');
  assert.equal(r.stdout,JSON.stringify({text:'abc',applied:0})+'\n');
});

test('CLI: empty transaction succeeds',()=>{
  const p=writeJson('empty.json',{source:'tail\r\n',edits:[]});
  const r=runCli([p]);
  assert.equal(r.status,0);
  assert.equal(r.stdout,JSON.stringify({text:'tail\r\n',applied:0})+'\n');
});

test('CLI: zero arguments exits 2 with stderr, no stdout',()=>{
  const r=runCli([]);
  assert.equal(r.status,2);
  assert.ok(r.stderr.length>0);
  assert.equal(r.stdout,'');
});

test('CLI: two arguments exits 2 with stderr, no stdout',()=>{
  const r=runCli(['a','b']);
  assert.equal(r.status,2);
  assert.ok(r.stderr.length>0);
  assert.equal(r.stdout,'');
});

test('CLI: unreadable file exits 2 with stderr, no stdout',()=>{
  const r=runCli([join(dir,'no-such-file.json')]);
  assert.equal(r.status,2);
  assert.ok(r.stderr.length>0);
  assert.equal(r.stdout,'');
});

test('CLI: invalid JSON exits 2 with stderr, no stdout',()=>{
  const p=writeRaw('bad.json','{ this is not json');
  const r=runCli([p]);
  assert.equal(r.status,2);
  assert.ok(r.stderr.length>0);
  assert.equal(r.stdout,'');
});

test('CLI: invalid transaction exits 2 with stderr, no stdout',()=>{
  const p=writeJson('inv.json',{source:'abc',edits:[{start:5,end:6,before:'',after:''}]});
  const r=runCli([p]);
  assert.equal(r.status,2);
  assert.ok(r.stderr.length>0);
  assert.equal(r.stdout,'');
});

test('CLI: conflicting transaction exits 2 with stderr, no stdout',()=>{
  const p=writeJson('conf.json',{source:'abcd',edits:[edit(0,2,'ab','x'),edit(1,3,'bc','y')]});
  const r=runCli([p]);
  assert.equal(r.status,2);
  assert.ok(r.stderr.length>0);
  assert.equal(r.stdout,'');
