test('CLI: missing edits field exits 2 with stderr, no stdout',()=>{
  const p=writeJson('noedits.json',{source:'abc'});
  const r=runCli([p]);
  assert.equal(r.status,2);
  assert.ok(r.stderr.length>0);
  assert.equal(r.stdout,'');
