test('CLI: non-object JSON top-level exits 2',()=>{
  const p=writeRaw('scalar.json','"just a string"');
  const r=runCli([p]);
  assert.equal(r.status,2);
  assert.ok(r.stderr.length>0);
  assert.equal(r.stdout,'');
});

